const fs = require('fs');
const path = require('path');

// clean-deploy-files.json 읽기
const cleanFiles = JSON.parse(fs.readFileSync(path.join(__dirname, 'clean-deploy-files.json'), 'utf8'));

// vercel deploy 호환을 위해 필수 파일만 골라내기
const targetFiles = cleanFiles.filter(f => !f.file.startsWith('scripts/') && f.file !== 'init.sql');

console.log(`Total files ready for Vercel deployment: ${targetFiles.length}`);
targetFiles.forEach(f => console.log(' -> ' + f.file));

// mcp_payload.json 생성
const payload = {
  name: "exercise-tracker",
  target: "production",
  teamId: "team_f3bRLwEMdEoBAgEADTQbK3Dt",
  files: targetFiles
};

fs.writeFileSync(path.join(__dirname, 'mcp_payload.json'), JSON.stringify(payload));
console.log("Successfully generated mcp_payload.json!");

const fs = require('fs');
const path = require('path');

function getAllFiles(dirPath, arrayOfFiles = []) {
  const files = fs.readdirSync(dirPath);

  files.forEach((file) => {
    const fullPath = path.join(dirPath, file);
    if (file === 'node_modules' || file === '.next' || file === '.git' || file === '.vercel') {
      return;
    }
    if (fs.statSync(fullPath).isDirectory()) {
      arrayOfFiles = getAllFiles(fullPath, arrayOfFiles);
    } else {
      const relPath = path.relative(path.join(__dirname, '..'), fullPath).replace(/\\/g, '/');
      const data = fs.readFileSync(fullPath, 'utf8');
      arrayOfFiles.push({ file: relPath, data });
    }
  });

  return arrayOfFiles;
}

const files = getAllFiles(path.join(__dirname, '..'));
console.log(`Total files to deploy: ${files.length}`);
fs.writeFileSync(path.join(__dirname, 'vercel-files.json'), JSON.stringify(files, null, 2));
console.log('Saved vercel-files.json');

const { Pool } = require('pg');
const fs = require('fs');
const path = require('path');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgres://postgres:postgres@localhost:5432/postgres',
});

async function init() {
  console.log('Connecting to PostgreSQL database...');
  const client = await pool.connect();
  try {
    const sql = fs.readFileSync(path.join(__dirname, '../init.sql'), 'utf-8');
    await client.query(sql);
    console.log('✅ Database schema and seed data initialized successfully!');
  } catch (err) {
    console.error('❌ DB Init Error:', err);
  } finally {
    client.release();
    await pool.end();
  }
}

init();

