import { useState, useEffect, useCallback } from 'react';
import { ExerciseCategory, UnitType } from '@/lib/types';
import { Dumbbell, Plus, Eye, EyeOff, Trash2, CheckCircle, Tag, Loader2 } from 'lucide-react';

export default function ExercisesPage() {
  const [categories, setCategories] = useState<ExerciseCategory[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [showAddForm, setShowAddForm] = useState<boolean>(false);

  const [name, setName] = useState<string>('');
  const [unitType, setUnitType] = useState<UnitType>('SET_REPS');
  const [categoryTag, setCategoryTag] = useState<string>('상체');
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);

  const fetchCategories = useCallback(async () => {
    setIsLoading(true);
    try {
      const res = await fetch('/api/categories');
      if (res.ok) {
        const data = await res.json();
        setCategories(data);
      }
    } catch (err) {
      console.error('Fetch categories error:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchCategories();
  }, [fetchCategories]);

  // 새 운동 종목 추가
  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    setIsSubmitting(true);

    try {
      const res = await fetch('/api/categories', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name,
          unit_type: unitType,
          category_tag: categoryTag,
        }),
      });

      if (res.ok) {
        setName('');
        setShowAddForm(false);
        fetchCategories();
      }
    } catch (err) {
      alert('운동 종목 추가 중 오류가 발생했습니다.');
    } finally {
      setIsSubmitting(false);
    }
  };

  // 활성화/숨김 상태 토글
  const handleToggleActive = async (id: string, currentActive: boolean) => {
    try {
      const res = await fetch('/api/categories', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, is_active: !currentActive }),
      });
      if (res.ok) {
        fetchCategories();
      }
    } catch (err) {
      console.error('Toggle error:', err);
    }
  };

  // 종목 삭제
  const handleDeleteCategory = async (id: string, catName: string) => {
    if (!confirm(`'${catName}' 종목을 정말 삭제하시겠습니까?`)) return;

    try {
      const res = await fetch(`/api/categories?id=${id}`, {
        method: 'DELETE',
      });
      if (res.ok) {
        fetchCategories();
      }
    } catch (err) {
      alert('삭제 중 오류가 발생했습니다.');
    }
  };

  return (
    <div className="p-4 space-y-6 pb-20">
      {/* 헤더 */}
      <div className="flex items-center justify-between border-b border-slate-800 pb-3">
        <div className="flex items-center gap-2">
