      {showAddForm && (
        <form
          onSubmit={handleAddCategory}
          className="bg-slate-800/90 border border-emerald-500/40 rounded-2xl p-4 space-y-4 shadow-xl"
        >
          <h3 className="font-bold text-slate-100 text-sm flex items-center gap-1.5">
